package com.hotelmanagement.hms.order.web; import com.hotelmanagement.hms.order.dto.*; import com.hotelmanagement.hms.order.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import org.springframework.http.HttpStatus; import java.util.*; @RestController @RequestMapping("/api/v1/hotels/{hotel}/branches/{branch}/orders") public class OrderController{private final OrderService s;public OrderController(OrderService s){this.s=s;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public OrderResponse create(@PathVariable UUID hotel,@PathVariable UUID branch,@Valid @RequestBody OrderRequest r){return s.create(hotel,branch,r);} @PostMapping("/{id}/send") public OrderResponse send(@PathVariable UUID hotel,@PathVariable UUID branch,@PathVariable UUID id){return s.send(hotel,branch,id);} @PostMapping("/{id}/void") @ResponseStatus(HttpStatus.NO_CONTENT) public void voidOrder(@PathVariable UUID hotel,@PathVariable UUID branch,@PathVariable UUID id){s.voidOrder(hotel,branch,id);}}
